  async function saveExcerpt(l, s, anns) {
    if (!s?.text?.trim()) throw Error("请先选择原文");
    const annotations =
      anns || l.annotations.filter((a) => a.start < s.end && a.end > s.start);
    const existing = pair.excerpts.find(
      (x) => x.letterId === l.id && x.start === s.start && x.end === s.end,
    );
    if (existing) {
      for (const a of annotations)
        if (!existing.annotations.some((x) => x.id === a.id))
          existing.annotations.push(copy(a));
    } else
      pair.excerpts.push({
        id: uid(),
        letterId: l.id,
        author: l.author,
        text: s.text,
        start: s.start,
        end: s.end,
        annotations: copy(annotations),
        createdAt: Date.now(),
      });
    await save();
    showToast("已收藏摘录" + (annotations.length ? "与批注" : ""));
  }
