  function calendar() {
    const controls = E("div", undefined, "xd-month-controls"),
      [y, m] = month.split("-").map(Number),
      year = E("input"),
      mon = E("select");
    year.type = "number";
    year.min = "1900";
    year.max = "9999";
    year.value = y;
    year.setAttribute("aria-label", "年份");
    for (let i = 1; i <= 12; i++) {
      const o = E("option", i + "月");
      o.value = i;
      mon.append(o);
    }
    mon.value = m;
    const update = () => {
      const yy = Number(year.value);
      if (!Number.isInteger(yy) || yy < 1900 || yy > 9999) return;
      month = yy + "-" + String(mon.value).padStart(2, "0");
      paint();
    };
    year.onchange = update;
    mon.onchange = update;
    function shift(n) {
      const d = new Date(y, m - 1 + n, 1);
      month = day(d).slice(0, 7);
      paint();
    }
    const yearGroup = E("label", undefined, "xd-year-choice");
    yearGroup.append(year, E("span", "年"));
    controls.append(
      IB("back", "上个月", () => shift(-1)),
      yearGroup,
      mon,
      IB("back", "下个月", () => shift(1), "xd-next"),
    );
    body.append(
      controls,
      B(
        "回到今天",
        () => {
          selected = day();
          month = selected.slice(0, 7);
          paint();
        },
        "xd-text xd-today",
      ),
    );
    const grid = E("div", undefined, "xd-calendar-grid");
    for (const s of ["一", "二", "三", "四", "五", "六", "日"])
      grid.append(E("small", s, "xd-muted"));
    const start = (new Date(y, m - 1, 1).getDay() + 6) % 7,
      count = new Date(y, m, 0).getDate();
    for (let i = 0; i < start; i++) grid.append(E("span"));
    const dates = new Set(
      pair.letters
        .filter((l) => authorFilter === "all" || l.author === authorFilter)
        .map((l) => day(l.createdAt)),
    );
    for (let i = 1; i <= count; i++) {
      const value = month + "-" + String(i).padStart(2, "0"),
        b = B(
          String(i),
          () => {
            selected = value;
            paint();
          },
          "xd-day" +
            (selected === value ? " selected" : "") +
            (value === day() ? " today" : ""),
        );
      if (dates.has(value)) b.append(E("i"));
      grid.append(b);
    }
    body.append(grid, E("p", "圆点表示当天有信件", "xd-calendar-hint"));
    const rows = sorted(
      pair.letters.filter(
        (l) =>
          day(l.createdAt) === selected &&
          (authorFilter === "all" || l.author === authorFilter),
      ),
    );
    const sub = E("div", undefined, "xd-date-heading"),
      label = E("div", undefined, "xd-selected-date");
    label.append(
      E(
        "strong",
        Number(selected.slice(5, 7)) + "月" + Number(selected.slice(8)) + "日",
      ),
      E("small", rows.length + "封信", "xd-muted"),
    );
    sub.append(
      label,
      authorTabs((k) => {
        authorFilter = k;
        paint();
      }),
    );
    body.append(sub);
    for (const l of rows) {
      const row = E("article", undefined, "xd-letter xd-calendar-result"),
        main = E("div", undefined, "xd-letter-main"),
        preview = E("div", contentText(l.html), "xd-calendar-preview");
      fontStyle(preview, pair, l.author);
      row.append(avatar(pair, l.author));
      main.append(
        byline(pair, l.author),
        E("time", stamp(l.createdAt), "xd-time"),
      );
      if (l.title) main.append(E("strong", l.title));
      main.append(
        preview,
        B("查看完整信件", () => navigate("read", { letter: l }), "xd-text"),
      );
      row.append(main);
      body.append(row);
    }
    if (rows.length)
      body.append(E("p", "已显示当天全部信件", "xd-calendar-end"));
  }

  function search() {
    const input = E("input", undefined, "xd-search");
    input.placeholder = "搜索标题、正文或批注";
    input.value = query;
    const results = E("div");
    function render() {
      query = input.value;
      results.replaceChildren();
      const rows = sorted(
        pair.letters.filter(
          (l) =>
            !query ||
            (
              (l.title || "") +
              " " +
              contentText(l.html) +
              " " +
              l.annotations.map((a) => a.text).join(" ")
            )
              .toLowerCase()
              .includes(query.toLowerCase()),
        ),
      );
      for (const l of rows) results.append(letterRow(l));
      if (!rows.length) results.append(empty("没有找到相关信件"));
    }
    input.oninput = render;
    body.append(input, results);
    render();
  }
  async function deleteLetter(c, p, l) {
    if (!p.letters.includes(l)) throw Error("这封信已不存在");
    const before = p.letters, oldDeleted = p.deletedLetterIds;
    const affected = Object.values(p.requests).filter(j => j.targetId === l.id || j.replyId === l.id);
    const statuses = affected.map(j => [j, j.status]);
    p.letters = before.filter(x => x.id !== l.id);
    p.deletedLetterIds = [...new Set([...(oldDeleted || []), l.id])];
    for (const job of affected) job.status = "cancelled";
    try { await save(c); }
    catch (e) {
      p.letters = before;p.deletedLetterIds = oldDeleted;
      for (const [job, status] of statuses) job.status = status;
      throw e;
    }
    translationOriginal.delete(p.id + ":" + l.id);
    if (current === c && pair === p) {
      if (reading?.id === l.id) { reading = null;navigate("home"); }
      else paint();
    }
    showToast("这封信已删除");
  }
