  async function loadFonts(p, { strict = false } = {}) {
    for (const side of ["user", "char"]) {
      const f = p.settings.fonts[side];
      if (!f) continue;
      try {
        if (f.url) {
          const url = new URL(f.url);
          if (!["https:", "http:"].includes(url.protocol))
            throw Error("请填写字体文件的 http(s) 链接");
          let hash = 2166136261;
          for (const ch of url.href)
            hash = Math.imul(hash ^ ch.charCodeAt(0), 16777619);
          const family = "ExchangeURL_" + (hash >>> 0).toString(16);
          if (![...document.fonts].some((x) => x.family === family)) {
            const face = new FontFace(
              family,
              "url(" + JSON.stringify(url.href) + ")",
            );
            await face.load();
            document.fonts.add(face);
          }
          f.family = family;
          continue;
        }
        if (!f.id || ["serif", "hand"].includes(f.id)) continue;
        const family = "ExchangeFont_" + f.id.replace(/\W/g, "");
        if (![...document.fonts].some((x) => x.family === family)) {
          const r = await dexieDB.customFonts.get(f.id);
          if (!r?.file) continue;
          const face = new FontFace(family, await r.file.arrayBuffer());
          await face.load();
          document.fonts.add(face);
        }
        f.family = family;
      } catch (e) {
        console.warn("日记字体加载失败", e);
        if (strict)
          throw Error(
            profile(p, side).name + "的字体加载失败，请检查字体直链及跨域权限",
          );
      }
    }
  }
